import {
  Component,
  OnInit,
  ChangeDetectionStrategy,
  Inject,
  ElementRef,
  ChangeDetectorRef,
  HostBinding
} from '@angular/core';
import { DOCUMENT } from '@angular/common';
import { NavigationEnd, Router } from '@angular/router';
import { filter, takeUntil } from 'rxjs/operators';
import { DestroySubject, LocalStorageService } from '@honoregaming/core';
import { CustomerOperatorConfiguration, customerOperatorConfigurationToken } from '@honoregaming/customer-core';
import { environment } from 'projects/customer/customer/src/environments/environment';
import { ThemeSwitcherService } from '../../services';
import { THEMES_INFO } from '../../constants/themes-info.constant';
import { ThemeInfo } from '../../models/theme-info.model';

@Component({
  selector: 'hg-theme-selector',
  templateUrl: './theme-selector.component.html',
  styleUrls: ['./theme-selector.component.scss'],
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class ThemeSelectorComponent extends DestroySubject implements OnInit {
  public operators: ThemeInfo[] = [];
  public currentOperator?: ThemeInfo;

  opened: boolean = false;

  private clickListenerFunction: any;
  public hide: boolean = false;
  dev: boolean = !environment.production;

  @HostBinding('class.mobile-opening') mobileOpening = false;

  constructor(
    private readonly element: ElementRef,
    private readonly cdRef: ChangeDetectorRef,
    public readonly themeSwitcherService: ThemeSwitcherService,
    private readonly router: Router,
    private readonly localStorageService: LocalStorageService,
    @Inject(customerOperatorConfigurationToken) private readonly operatorConfiguration: CustomerOperatorConfiguration,
    @Inject(DOCUMENT) private readonly document: Document
  ) {
    super();
  }

  ngOnInit(): void {
    this.operators = THEMES_INFO;

    const themeStorageValue = this.localStorageService.getItem('theme-key');
    if (themeStorageValue) {
      this.currentOperator = this.operators.find(o => o.key === themeStorageValue);
    }

    if (!this.currentOperator) {
      this.currentOperator = this.operators.find(o => o.key === this.operatorConfiguration.commercialCode);
    }

    if (!this.currentOperator) {
      this.currentOperator = this.operators.find(o => o.key === 'UY');
    }

    this.checkDisplayForInsaGames(this.router.url);

    this.router.events
      .pipe(filter(event => event instanceof NavigationEnd))
      .pipe(takeUntil(this.destroy$))
      .subscribe((event: NavigationEnd) => {
        this.checkDisplayForInsaGames(event.urlAfterRedirects);
      });
  }

  changeTheme(theme: ThemeInfo): void {
    this.opened = false;
    this.mobileOpening = false;
    this.document.removeEventListener('click', this.clickListenerFunction);
    this.currentOperator = theme;

    this.themeSwitcherService.loadStyle(theme.key);
  }

  toggleThemesSelector(): void {
    this.opened = !this.opened;
    this.mobileOpening = !this.mobileOpening;
    if (this.opened) {
      this.clickListenerFunction = this.closeSelectorOnFocusOut.bind(this);
      setTimeout(() => this.document.addEventListener('click', this.clickListenerFunction), 0);
    }
  }

  private closeSelectorOnFocusOut(ev: MouseEvent): void {
    if (!(<Node>this.element.nativeElement).contains(<Node>ev.target)) {
      this.opened = false;
      this.mobileOpening = false;
      this.document.removeEventListener('click', this.clickListenerFunction);
      this.cdRef.markForCheck();
    }
  }

  private checkDisplayForInsaGames(url: string): void {
    this.hide = url.includes('/ig/');
    this.cdRef.markForCheck();
  }
}
